out2=[row[:] for row in grid]
# fill between consecutive 8s in each row
for r,row in enumerate(grid):
    ps=[c for c,v in enumerate(row) if v==8]
    for a,b in zip(ps,ps[1:]):
        for c in range(a+1,b): out2[r][c]=3
# and each column
for c in range(8):
    ps=[r for r in range(21) if grid[r][c]==8]
    for a,b in zip(ps,ps[1:]):
        for r in range(a+1,b): out2[r][c]=3
print('\n'.join(str(row) for row in out2))
